//go:build bdd

// Code generated by `true-bdd build tests`. DO NOT EDIT.
//
// Source: docs/scenarios.yaml
//
// One Go test per registry scenario, with the scenario's steps stated
// literally: what a reader sees here is what the machine runs. Done
// checks these steps against the registry before running any of them,
// so a hand edit to either side fails the test rather than quietly
// making the two documents disagree.
//
// Scenarios sharing a `path:` are written here in id order, so an
// inserted scenario lands where a reader expects it instead of at the
// end. Sequential by design — the suite's harness is shared.

package mcp_test

import (
	"testing"

	"fixture/buildtests/tests/mcp/scenarios"
)

// E2E-900: MCP /mcp endpoint responds 400 to a malformed POST
func TestE2E900(t *testing.T) {
	s := scenarios.New(t, "E2E-900")
	s.Given(`the MCP server is running on its configured port`)
	s.When(`the Claude User posts a malformed JSON-RPC request to /mcp`)
	s.Then(`the server returns HTTP 400`)
	s.Done()
}

// mcp-endpoint-001-initialize-ok: MCP /mcp endpoint responds 200 to a valid initialize POST
func TestMcpEndpoint001InitializeOk(t *testing.T) {
	s := scenarios.New(t, "mcp-endpoint-001-initialize-ok")
	s.Given(`the MCP server is running on its configured port`)
	s.When(`the Claude User posts a valid JSON-RPC initialize request to /mcp`)
	s.Then(`the server returns HTTP 200`)
	s.Done()
}
